style:
.etp-pro {
  border-radius: 12px;
  border: 1px solid #d8dee8;
  background: linear-gradient(180deg, #ffffff 0%, #f7f9fc 100%);
  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.04), 0 8px 24px rgba(16, 24, 40, 0.06);
  overflow: hidden;
}
.etp-pro__row {
  display: flex;
  gap: 28px;
  justify-content: space-between;
  align-items: stretch;
  flex-wrap: wrap;
  padding: 28px 30px;
  border-top: 3px solid #1f4b99;
}
.etp-pro__copy {
  flex: 1 1 360px;
  max-width: 640px;
}
.etp-pro__eyebrow {
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #1f4b99;
  margin-bottom: 8px;
}
.etp-pro__title {
  margin: 0 0 8px;
  font-size: 28px;
  line-height: 1.15;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: #101828;
}
.etp-pro__desc {
  margin: 0 0 16px;
  font-size: 14px;
  line-height: 1.55;
  color: #475467;
  max-width: 540px;
}
.etp-pro__meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  font-size: 12px;
  color: #667085;
}
.etp-pro__status {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 4px 10px;
  border-radius: 999px;
  background: #eff4ff;
  color: #175cd3;
  border: 1px solid #b2ccff;
  font-weight: 600;
}
.etp-pro__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #2970ff;
}
.etp-pro__sep {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #98a2b3;
}
.etp-pro__facts {
  flex: 0 0 250px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  justify-content: center;
}
.etp-pro__fact {
  padding: 12px 14px;
  border-radius: 10px;
  background: #ffffff;
  border: 1px solid #e4e7ec;
}
.etp-pro__fact-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #98a2b3;
  margin-bottom: 4px;
}
.etp-pro__fact-value {
  font-size: 14px;
  font-weight: 650;
  color: #101828;
}
@media (max-width: 768px) {
  .etp-pro__row { padding: 20px; }
  .etp-pro__title { font-size: 24px; }
  .etp-pro__facts { flex-basis: 100%; }
}
